def register_search_callback(app):
    @app.callback(
        Output("search-results", "children"),
        Output("tag-list", "children"),
        Output("search-status", "children"),
        Input("btn-search", "n_clicks"),
        Input("btn-list-tags", "n_clicks"),
        State("search-input", "value"),
        State("input-folder", "value"),
        prevent_initial_call=True,
    )
    def run_search(btn_search, btn_list_tags, query, folder):
        if not folder:
            return (
                dash.no_update,
                dash.no_update,
                dbc.Alert("Enter a folder path above before searching.", color="warning"),
            )

        db_path = FeaturesDatabase.default_db_path(folder)
        if not db_path.exists():
            return (
                dash.no_update,
                dash.no_update,
                dbc.Alert(
                    "No features.db found for this folder. Process the folder first.",
                    color="warning",
                ),
            )

        db = FeaturesDatabase(db_path)
        triggered_id = callback_context.triggered_id

        if triggered_id == "btn-list-tags":
            tags = db.list_all_tags()
            if not tags:
                return (
                    dash.no_update,
                    html.Div("No tags found.", className="text-muted"),
                    dash.no_update,
                )
            badges = [dbc.Badge(t, color="info", className="me-1 mb-1") for t in tags]
            return (
                dash.no_update,
                html.Div(badges, className="d-flex flex-wrap"),
                dash.no_update,
            )

        if triggered_id == "btn-search":
            if not query:
                return (
                    dash.no_update,
                    dash.no_update,
                    dbc.Alert("Enter a search query.", color="warning"),
                )
            results = db.search_features(query)
            if not results:
                return (
                    html.Div("No results found.", className="text-muted"),
                    dash.no_update,
                    dash.no_update,
                )
            table = build_search_results(results)
            return (
                table,
                dash.no_update,
                dbc.Alert(f"{len(results)} result(s) found.", color="success", dismissable=True),
            )

        return dash.no_update, dash.no_update, dash.no_update


